$base = "D:\.1 Work Stations\RootMC"

Write-Host "=== DEPLOY LOGS ==="
foreach ($f in @(
  "$base\Web Files\rootmc-web\_deploy-last.log",
  "$base\Web Files\rootmc-api\_deploy-last.log",
  "$base\Web Files\rootmc-api\.last-deploy-live.log"
)) {
  if (Test-Path $f) {
    Write-Host ("`n" + $f + " mtime=" + (Get-Item $f).LastWriteTime)
    Get-Content $f -Tail 12
  }
}

Write-Host "`n=== NEWEST FILES ==="
function Get-NewestFile([string]$path) {
  if (!(Test-Path $path)) { return $null }
  Get-ChildItem $path -Recurse -File -ErrorAction SilentlyContinue |
    Where-Object { $_.FullName -notmatch 'node_modules|\.git\\|\\\.wrangler\\|\\target\\' } |
    Sort-Object LastWriteTime -Descending |
    Select-Object -First 1
}

$pairs = @(
  @("web/public", "$base\Web Files\rootmc-web\public"),
  @("web/build", "$base\Web Files\rootmc-web\build"),
  @("web/functions", "$base\Web Files\rootmc-web\functions"),
  @("realm-api/src", "$base\Web Files\rootmc-realm-api\src"),
  @("api/src", "$base\Web Files\rootmc-api\src"),
  @("shared", "$base\Web Files\shared"),
  @("app/src", "$base\Web Files\rootmc-app\src"),
  @("app/build", "$base\Web Files\rootmc-app\build"),
  @("webstat-proxy", "$base\Web Files\rootmc-webstat-proxy"),
  @("minecraft-map", "$base\Web Files\rootmc-minecraft-map"),
  @("plugins src", "$base\Plugin Building\Minecraft\plugins")
)

foreach ($p in $pairs) {
  $n = Get-NewestFile $p[1]
  if ($n) { Write-Host ("{0,-18} {1}  {2}" -f $p[0], $n.LastWriteTime.ToString("yyyy-MM-dd HH:mm"), $n.Name) }
  else { Write-Host ("{0,-18} MISSING" -f $p[0]) }
}

Write-Host "`n=== rootmc-app (no node_modules) ==="
Get-ChildItem "$base\Web Files\rootmc-app" -Force | Where-Object { $_.Name -ne "node_modules" } | Format-Table Name, Mode, LastWriteTime -AutoSize

Write-Host "`n=== Plugin jars in handoffs vs gradle ==="
$pluginsRoot = "$base\Plugin Building\Minecraft\plugins"
Get-ChildItem $pluginsRoot -Directory -ErrorAction SilentlyContinue | ForEach-Object {
  $bg = Join-Path $_.FullName "build.gradle.kts"
  if (!(Test-Path $bg)) { return }
  $ver = if ((Get-Content $bg -Raw) -match 'version\s*=\s*"([^"]+)"') { $Matches[1] } else { "?" }
  $srcNewest = Get-ChildItem $_.FullName -Recurse -File -Include *.kt,*.java,*.yml -EA SilentlyContinue |
    Where-Object { $_.FullName -notmatch '\\build\\' } | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  $jar = Get-ChildItem (Join-Path $_.FullName "build\libs") -Filter "*.jar" -EA SilentlyContinue | Sort-Object LastWriteTime -Descending | Select-Object -First 1
  $srcT = if ($srcNewest) { $srcNewest.LastWriteTime.ToString("MM-dd HH:mm") } else { "n/a" }
  $jarT = if ($jar) { $jar.LastWriteTime.ToString("MM-dd HH:mm") } else { "NO JAR" }
  $stale = if ($srcNewest -and $jar -and $srcNewest.LastWriteTime -gt $jar.LastWriteTime.AddMinutes(1)) { "STALE" } elseif (!$jar) { "MISSING" } else { "ok" }
  if ($stale -ne "ok") { Write-Host ("{0,-28} v{1,-10} src={2} jar={3} {4}" -f $_.Name, $ver, $srcT, $jarT, $stale) }
}
Write-Host "(only stale/missing shown above)"

