$zoneId = $env:CLOUDFLARE_ZONE_ID
$headers = @{ Authorization = "Bearer $token"; "Content-Type" = "application/json" }

function Ensure-PagesDomain($projectName, $domain) {
  Write-Host "=== $domain -> $projectName ==="
  $project = Invoke-RestMethod -Method Get -Uri "https://api.cloudflare.com/client/v4/accounts/$accountId/pages/projects/$projectName" -Headers $headers
  if (-not $project.success) { throw ($project | ConvertTo-Json -Compress) }
  $pagesTarget = [string]$project.result.subdomain
  if ($pagesTarget -notmatch '\.pages\.dev$') { $pagesTarget = "$pagesTarget.pages.dev" }
  Write-Host "Pages target: $pagesTarget domains=$($project.result.domains -join ',')"
  if ($project.result.domains -notcontains $domain) {
    try {
      $body = @{ name = $domain } | ConvertTo-Json -Compress
      $add = Invoke-RestMethod -Method Post -Uri "https://api.cloudflare.com/client/v4/accounts/$accountId/pages/projects/$projectName/domains" -Headers $headers -Body $body
      Write-Host ("Added pages domain: " + ($add | ConvertTo-Json -Compress))
    } catch { Write-Host "Pages domain add: $($_.Exception.Message)" }
  } else { Write-Host "Pages domain already present" }

  $existing = Invoke-RestMethod -Method Get -Uri "https://api.cloudflare.com/client/v4/zones/$zoneId/dns_records?type=CNAME&name=$domain" -Headers @{ Authorization = "Bearer $token" }
  $dnsName = ($domain -split '\.')[0]
  $bodyObj = @{ type="CNAME"; name=$dnsName; content=$pagesTarget; proxied=$true; ttl=1 }
  if ($existing.result.Count -gt 0) {
    $id = $existing.result[0].id
    $upd = Invoke-RestMethod -Method Put -Uri "https://api.cloudflare.com/client/v4/zones/$zoneId/dns_records/$id" -Headers $headers -Body ($bodyObj | ConvertTo-Json -Compress)
    Write-Host ("Updated DNS: " + $upd.success + " " + $existing.result[0].content + " -> " + $pagesTarget)
  } else {
    $cre = Invoke-RestMethod -Method Post -Uri "https://api.cloudflare.com/client/v4/zones/$zoneId/dns_records" -Headers $headers -Body ($bodyObj | ConvertTo-Json -Compress)
    Write-Host ("Created DNS: " + $cre.success + " -> " + $pagesTarget)
  }
}

