input.contents:
/**
 * Post to a Slack Incoming Webhook (hooks.slack.com).
 * Prefer this over Discord for migrated ops destinations.
 */
export async function postSlackIncomingWebhook(
  webhookUrl: string,
  payload: { text?: string; blocks?: unknown[]; attachments?: unknown[] },
): Promise<{ ok: boolean; status: number; body: string }> {
  const url = String(webhookUrl || "").trim();
  if (!/^https:\/\/hooks\.slack\.com\/services\//i.test(url)) {
    return { ok: false, status: 0, body: "invalid_webhook_url" };
  }
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json; charset=utf-8" },
    body: JSON.stringify(payload),
  });
  const body = await res.text().catch(() => "");
  // Slack returns "ok" as plain text on success for Incoming Webhooks.
  const ok = res.ok && (body === "ok" || body.trim() === "" || body.startsWith("{"));
  return { ok: res.ok && (body === "ok" || res.status === 200), status: res.status, body: body.slice(0, 400) };
}

export function slackFeedbackWebhook(env: { SLACK_FEEDBACK_WEBHOOK_URL?: string }): string {
  return String(env.SLACK_FEEDBACK_WEBHOOK_URL || "").trim();
}

export function slackFeedbackChannelId(env: { SLACK_FEEDBACK_CHANNEL_ID?: string }): string {
  return String(env.SLACK_FEEDBACK_CHANNEL_ID || "").trim() || "C0BLMGBVAMD";
}

/**
 * Post to a Slack Incoming Webhook (hooks.slack.com).
 * Prefer this over Discord for migrated ops destinations.
 */
export async function postSlackIncomingWebhook(
  webhookUrl: string,
  payload: { text?: string; blocks?: unknown[]; attachments?: unknown[] },
): Promise<{ ok: boolean; status: number; body: string }> {
  const url = String(webhookUrl || "").trim();
  if (!/^https:\/\/hooks\.slack\.com\/services\//i.test(url)) {
    return { ok: false, status: 0, body: "invalid_webhook_url" };
  }
  const res = await fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json; charset=utf-8" },
    body: JSON.stringify(payload),
  });
  const body = await res.text().catch(() => "");
  // Incoming Webhooks return plain text "ok" on success.
  return { ok: res.ok && body.trim() === "ok", status: res.status, body: body.slice(0, 400) };
}

export function slackFeedbackWebhook(env: { SLACK_FEEDBACK_WEBHOOK_URL?: string }): string {
  return String(env.SLACK_FEEDBACK_WEBHOOK_URL || "").trim();
}

/** Default: Slack #feedback (migrated from Discord 1516828735536365669). */
export function slackFeedbackChannelId(env: { SLACK_FEEDBACK_CHANNEL_ID?: string }): string {
  return String(env.SLACK_FEEDBACK_CHANNEL_ID || "").trim() || "C0BLMGBVAMD";
}

import { json } from "./cors";
import { record, str } from "./realm-lib";
import type { RootStatEnv } from "./rootstat-minecraft";
import { validateServerAuth } from "./rootstat-minecraft";
import {
  postSlackIncomingWebhook,
  slackFeedbackChannelId,
  slackFeedbackWebhook,
} from "./slack-incoming-webhook";

type FeedbackEnv = RootStatEnv & {
  SLACK_FEEDBACK_WEBHOOK_URL?: string;
  SLACK_FEEDBACK_CHANNEL_ID?: string;
};

function stripMcColors(text: string): string {
  return text.replace(/§[0-9a-fk-or]/gi, "").replace(/&[0-9a-fk-or]/gi, "").trim();
}

function truncate(s: string, max: number): string {
  if (s.length <= max) return s;
  return s.slice(0, Math.max(0, max - 3)) + "...";
}

function safeText(s: string): string {
  return s.replace(/```/g, "'''").replace(/\r\n/g, "\n").trim();
}

/**
 * POST /api/rootmc/ingame-feedback — server-authenticated in-game player feedback → Slack #feedback.
 * Body: { uuid, username, message, server_name? } (legacy: world → treated as server_name)
 */
export async function handleRootMcIngameFeedback(
  request: Request,
  env: FeedbackEnv,
  subpath: string,
  method: string,
): Promise<Response | null> {
  if (!subpath.startsWith("/rootmc/ingame-feedback")) return null;

  if (method !== "POST" || subpath !== "/rootmc/ingame-feedback") {
    return json({ detail: "Not Found" }, 404);
  }

  const server = await validateServerAuth(env, request);
  if (server instanceof Response) return server;

  let body: Record<string, unknown>;
  try {
    body = record(JSON.parse(await request.text()));
  } catch {
    return json({ detail: "Invalid JSON body." }, 400);
  }

  const uuid = stripMcColors(str(body.uuid));
  const username = stripMcColors(str(body.username));
  const message = safeText(stripMcColors(str(body.message)));
  let serverName = stripMcColors(str(body.server_name) || str(body.world));

  if (!uuid || !username) {
    return json({ detail: "uuid and username are required." }, 400);
  }
  if (!message) {
    return json({ detail: "message is required." }, 400);
  }

  if (!serverName) {
    try {
      const row = await env.DB.prepare(
        `SELECT server_name FROM rootstat_servers WHERE server_id = ? LIMIT 1`,
      )
        .bind(server.serverId)
        .first<{ server_name: string | null }>();
      serverName = stripMcColors(str(row?.server_name));
    } catch {
      // optional lookup
    }
  }

  const webhook = slackFeedbackWebhook(env);
  const channelId = slackFeedbackChannelId(env);
  if (!webhook) {
    return json({ detail: "In-game feedback is not configured on the API (Slack webhook)." }, 503);
  }

  let text =
    `*In-game feedback*\n` +
    `*Player:* ${username}\n` +
    `*UUID:* \`${uuid}\`\n` +
    `*Server ID:* \`${server.serverId}\``;
  if (serverName) text += `\n*Server:* ${serverName}`;
  text += `\n\n*Message:*\n${truncate(message, 3200)}`;

  const posted = await postSlackIncomingWebhook(webhook, { text: truncate(text, 3900) });
  if (!posted.ok) {
    console.warn("ingame_feedback_slack_post_failed", posted.status, posted.body);
    return json({ detail: "Could not deliver feedback. Try again later." }, 502);
  }

  return json({ ok: true, channel_id: channelId, destination: "slack" }, 200);
}

import { json } from "./cors";
import { record, str } from "./realm-lib";
import type { RootStatEnv } from "./rootstat-minecraft";
import { validateServerAuth } from "./rootstat-minecraft";
import {
  postSlackIncomingWebhook,
  slackFeedbackChannelId,
  slackFeedbackWebhook,
} from "./slack-incoming-webhook";

type QuestionnaireEnv = RootStatEnv & {
  SLACK_FEEDBACK_WEBHOOK_URL?: string;
  SLACK_FEEDBACK_CHANNEL_ID?: string;
};

type AnswerRow = { id?: string; question?: string; answer?: string };

function stripMcColors(text: string): string {
  return text.replace(/§[0-9a-fk-or]/gi, "").replace(/&[0-9a-fk-or]/gi, "").trim();
}

function truncate(s: string, max: number): string {
  if (s.length <= max) return s;
  return s.slice(0, Math.max(0, max - 3)) + "...";
}

function safeText(s: string): string {
  return s.replace(/```/g, "'''").replace(/\r\n/g, "\n").trim();
}

/**
 * POST /api/rootmc/ingame-questionnaire — server-authenticated one-time survey → Slack #feedback.
 * Body: { uuid, username, world?, answers: [{ id, question, answer }] }
 */
export async function handleRootMcIngameQuestionnaire(
  request: Request,
  env: QuestionnaireEnv,
  subpath: string,
  method: string,
): Promise<Response | null> {
  if (!subpath.startsWith("/rootmc/ingame-questionnaire")) return null;

  if (method !== "POST" || subpath !== "/rootmc/ingame-questionnaire") {
    return json({ detail: "Not Found" }, 404);
  }

  const server = await validateServerAuth(env, request);
  if (server instanceof Response) return server;

  let body: Record<string, unknown>;
  try {
    body = record(JSON.parse(await request.text()));
  } catch {
    return json({ detail: "Invalid JSON body." }, 400);
  }

  const uuid = stripMcColors(str(body.uuid));
  const username = stripMcColors(str(body.username));
  const world = stripMcColors(str(body.world));
  const answersRaw = body.answers;

  if (!uuid || !username) {
    return json({ detail: "uuid and username are required." }, 400);
  }
  if (!Array.isArray(answersRaw) || answersRaw.length === 0) {
    return json({ detail: "answers array is required." }, 400);
  }

  const webhook = slackFeedbackWebhook(env);
  const channelId = slackFeedbackChannelId(env);
  if (!webhook) {
    return json({ detail: "In-game questionnaire is not configured on the API (Slack webhook)." }, 503);
  }

  const lines = (answersRaw as AnswerRow[]).slice(0, 25).map((row, index) => {
    const answer = record(row as Record<string, unknown>);
    const question = truncate(safeText(stripMcColors(str(answer.question || answer.id || `Q${index + 1}`))), 256);
    const value = truncate(safeText(stripMcColors(str(answer.answer))), 1024);
    return `• *${question}*\n  ${value || "(empty)"}`;
  });

  let text =
    `*Player questionnaire*\n` +
    `*Player:* ${username}\n` +
    `*UUID:* \`${uuid}\`\n` +
    `*Server ID:* \`${server.serverId}\``;
  if (world) text += `\n*World:* ${world}`;
  text += `\n\n${lines.join("\n")}`;

  const posted = await postSlackIncomingWebhook(webhook, { text: truncate(text, 3900) });
  if (!posted.ok) {
    console.warn("ingame_questionnaire_slack_post_failed", posted.status, posted.body);
    return json({ detail: "Could not deliver questionnaire. Try again later." }, 502);
  }

  return json({ ok: true, channel_id: channelId, destination: "slack" }, 200);
}

import { json } from "./cors";
import { record, str } from "./realm-lib";
import type { RootStatEnv } from "./rootstat-minecraft";
import { validateServerAuth } from "./rootstat-minecraft";
import {
  postSlackIncomingWebhook,
  slackFeedbackChannelId,
  slackFeedbackWebhook,
} from "./slack-incoming-webhook";

type ReportEnv = RootStatEnv & {
  SLACK_FEEDBACK_WEBHOOK_URL?: string;
  SLACK_FEEDBACK_CHANNEL_ID?: string;
