/** Oldest incomplete HST day at or before throughDayKey; null when caught up. */
export async function resolveDailyReportDayKey(
  db: D1Database,
  serverId: string,
  throughDayKey: string,
): Promise<string | null> {
  const latest = await latestCombinedReportDayKey(db, serverId);

  // Finish the latest combined day's suite (categories) before advancing  -  otherwise a
  // CPU timeout after the combined post leaves categories missing forever while cron
  // keeps attempting the next calendar day.
  if (latest && latest <= throughDayKey && !(await dailyReportSuiteComplete(db, serverId, latest))) {
    return latest;
  }

  let cursor = latest ? hstDayAfter(latest) : throughDayKey;
  while (cursor <= throughDayKey) {
    if (!(await dailyReportSuiteComplete(db, serverId, cursor))) {
      return cursor;
    }
    cursor = hstDayAfter(cursor);
  }
  return null;
}

