async function maybeRunDailyReports(env: Env, when: Date): Promise<void> {
  const throughDayKey = previousHstDayKey(when);
  const serverId = await resolveServerId(env.DB);

  const { runFullDailyReportSuite, runMissingDailyCategoryReports } = await import(
    "./rootmc-daily-report-runner"
  );
  const {
    combinedReportPosted,
    resolveDailyReportDayKey,
    resolveOldestIncompleteCategoryDayKey,
  } = await import("./rootmc-ai-report-store");

  // Category briefs first (one per tick) so a broken channel cannot stall combined catch-up.
  const categoryDayKey = await resolveOldestIncompleteCategoryDayKey(env.DB, serverId, throughDayKey);
  if (categoryDayKey) {
    const categories = await runMissingDailyCategoryReports(env, serverId, categoryDayKey, undefined, {
      limit: 1,
    });
    console.log(
      JSON.stringify({
        msg: "rootmc_daily_category_retry",
        dayKey: categoryDayKey,
        categories: categories.map((c) => `${c.category}:${c.detail}`),
      }),
    );
  }

  const dayKey = await resolveDailyReportDayKey(env.DB, serverId, throughDayKey);
  if (!dayKey || (await combinedReportPosted(env.DB, serverId, dayKey))) {
    return;
  }

  await runFullDailyReportSuite(env, { serverId, dayKey });
}

if (method === "POST" && sub === "/rootmc/daily-report/catch-up") {
  const server = await validateServerAuth(env, request);
  if (server instanceof Response) return server;
  const throughDayKey = previousHstDayKey();
  const categoryDayKey = await resolveOldestIncompleteCategoryDayKey(
    env.DB,
    server.serverId,
    throughDayKey,
  );
  if (categoryDayKey) {
    const categories = await runMissingDailyCategoryReports(
      env,
      server.serverId,
      categoryDayKey,
      undefined,
      { limit: 1 },
    );
    const pending = categories.filter((c) => c.detail !== "already posted");
    return json({
      ok: pending.every((c) => c.ok),
      server_id: server.serverId,
      dayKey: categoryDayKey,
      mode: "categories",
      through_day_key: throughDayKey,
      categories: categories.map((c) => ({ category: c.category, ok: c.ok, detail: c.detail })),
      remaining: pending.filter((c) => !c.ok).length,
    });
  }
  const dayKey = await resolveDailyReportDayKey(env.DB, server.serverId, throughDayKey);
  if (!dayKey) {
    return json({
      ok: true,
      server_id: server.serverId,
      through_day_key: throughDayKey,
      detail: "caught_up",
    });
  }
  if (await combinedReportPosted(env.DB, server.serverId, dayKey)) {
    return json({
      ok: true,
      server_id: server.serverId,
      dayKey,
      mode: "categories",
      through_day_key: throughDayKey,
      detail: "combined_present_categories_complete",
    });
  }
  ctx.waitUntil(
    runFullDailyReportSuite(env, {
      serverId: server.serverId,
      dayKey,
      previewLabel: "catch-up",
    }).catch((e) =>
      console.error("rootmc_daily_catch_up_failed", e instanceof Error ? e.message : String(e)),
    ),
  );
  return json({
    ok: true,
    server_id: server.serverId,
    dayKey,
    mode: "combined",
    through_day_key: throughDayKey,
    detail: "queued",
  });
}

