async function readLiveOnlinePlayers(db: D1Database, serverId: string): Promise<number | null> {
  const row = await db
    .prepare(
      `SELECT online_players, updated_at FROM rootmc_server_live_stats WHERE server_id = ? LIMIT 1`,
    )
    .bind(serverId)
    .first<{ online_players: number; updated_at: string }>();
  if (!row) return null;
  return Math.max(0, Math.floor(Number(row.online_players) || 0));
}

/** Prefer LIVE_DB Hyperdrive mirrors for dual-host economy (Towny + Claims). */
async function liveHostEconomySlice(
  liveDb: D1Database,
  serverId: string,
): Promise<{
  economy: Awaited<ReturnType<typeof economyTotals>>;
  netWorth: Awaited<ReturnType<typeof netWorthLeaderboard>>;
  playtime: Awaited<ReturnType<typeof playtimeLeaderboardForServer>>;
  linked: number;
} | null> {
  try {
    const bal = await liveDb
      .prepare(
        `SELECT minecraft_uuid, minecraft_username, balance, updated_at
         FROM m_root_economy_balances
         WHERE _server_id = ?`,
      )
      .bind(serverId)
      .all<{
        minecraft_uuid: string;
        minecraft_username: string;
        balance: string;
        updated_at: string;
      }>();

    const rows = (bal.results || [])
      .map((row) => {
        const uuid = str(row.minecraft_uuid).toLowerCase();
        const name = str(row.minecraft_username);
        const balance = Number(row.balance);
        if (!uuid || !Number.isFinite(balance) || balance <= 0) return null;
        if (isEconomySystemAccount(uuid, name)) return null;
        return {
          minecraft_uuid: uuid,
          minecraft_username: name || null,
          balance_value: balance,
          total_value: balance,
          synced_at: str(row.updated_at) || null,
        };
      })
      .filter((row): row is NonNullable<typeof row> => row !== null);

    if (rows.length === 0) return null;

    const totalBalance = rows.reduce((s, r) => s + r.balance_value, 0);
    const syncedAt = rows.map((r) => r.synced_at).filter(Boolean).sort().pop() || null;
    const netWorth = [...rows]
      .sort((a, b) => b.total_value - a.total_value)
      .slice(0, 15)
      .map((r) => ({
        minecraft_username: r.minecraft_username,
        total_value: r.total_value,
        balance_value: r.balance_value,
      }));

    const pt = await liveDb
      .prepare(
        `SELECT username, seconds
         FROM m_root_playtime
         WHERE _server_id = ?
         ORDER BY CAST(seconds AS REAL) DESC
         LIMIT 25`,
      )
      .bind(serverId)
      .all<{ username: string; seconds: string }>();

    const playtime = (pt.results || []).map((row) => ({
      minecraft_username: str(row.username) || null,
      total_playtime_seconds: Math.max(0, Math.floor(Number(row.seconds) || 0)),
    }));

    const linkedRow = await liveDb
      .prepare(
        `SELECT COUNT(DISTINCT uuid) AS c FROM m_root_playtime WHERE _server_id = ? AND CAST(seconds AS REAL) > 0`,
      )
      .bind(serverId)
      .first<{ c: number }>();

    return {
      economy: {
        trackedPlayers: rows.length,
        totalNetWorth: totalBalance,
        totalBalance,
        totalGoldMinted: 0,
        totalGoldMined: 0,
        shopListings: 0,
        pricedItems: 0,
        syncedAt,
      },
      netWorth,
      playtime,
      linked: Number(linkedRow?.c) || rows.length,
    };
  } catch (e) {
    console.warn(
      "rootmc_live_host_economy_slice_failed",
      serverId,
      e instanceof Error ? e.message : String(e),
    );
    return null;
  }
}

