export function formatHostComparisonAppendix(
  townyEco: EconomyTotals,
  claimsEco: EconomyTotals,
  labels?: { towny?: string; claims?: string },
  playtimeCounts?: { towny?: number; claims?: number },
): string {
  const t = labels?.towny || "Towny";
  const c = labels?.claims || "Claims";
  const line = (label: string, a: string | number, b: string | number) =>
    `- **${label}:** ${t} **${a}**  |  ${c} **${b}**`;
  const parts: string[] = [];
  if (playtimeCounts) {
    parts.push(
      line(
        "Players with playtime",
        playtimeCounts.towny ?? 0,
        playtimeCounts.claims ?? 0,
      ),
    );
  }
  parts.push(
    line("Gold in wallets", formatReportGold(townyEco.totalBalance), formatReportGold(claimsEco.totalBalance)),
    line("Combined net worth", formatReportGold(townyEco.totalNetWorth), formatReportGold(claimsEco.totalNetWorth)),
    line(
      "Gold mined (all-time)",
      formatReportGold(townyEco.totalGoldMined ?? townyEco.totalGoldMinted),
      formatReportGold(claimsEco.totalGoldMined ?? claimsEco.totalGoldMinted),
    ),
    line("Shop listings", townyEco.shopListings, claimsEco.shopListings),
    line("Players with wallets", townyEco.trackedPlayers, claimsEco.trackedPlayers),
  );
  return parts.join("\n");
}

function formatPlayLabel(seconds: number): string {
  const s = Math.max(0, Math.floor(Number(seconds) || 0));
  const d = Math.floor(s / 86400);
  const h = Math.floor((s % 86400) / 3600);
  const m = Math.floor((s % 3600) / 60);
  if (d > 0) return `${d}d ${h}h`;
  if (h > 0) return `${h}h ${m}m`;
  return `${m}m`;
}

type DualHostPlayRow = {
  minecraft_username?: string | null;
  total_playtime_seconds?: number | null;
};

/** Deterministic equal Towny/Claims daily body — do not leave host balance to the model. */
export function formatEqualDualHostDailyBody(input: {
  linked: number;
  towny: {
    economy: EconomyTotals;
    playersWithPlaytime: number;
    playtime: DualHostPlayRow[];
    netWorth: NetWorthRow[];
    townCount?: number;
    nationCount?: number;
    totalPlots?: number;
  };
  claims: {
    economy: EconomyTotals;
    playersWithPlaytime: number;
    playtime: DualHostPlayRow[];
    netWorth: NetWorthRow[];
    onlinePlayers?: number | null;
  };
}): string {
  const hostBlock = (
    title: string,
    host: {
      economy: EconomyTotals;
      playersWithPlaytime: number;
      playtime: DualHostPlayRow[];
      netWorth: NetWorthRow[];
    },
  ) => {
    const topPt = host.playtime[0];
    const topWallet = walletLeaderboardForPlayers(host.netWorth, 1)[0];
    const lines = [
      `## ${title}`,
      "",
      `- **Players with playtime:** **${host.playersWithPlaytime}**`,
      `- **Gold in wallets:** ${formatReportGold(host.economy.totalBalance)} (**${host.economy.trackedPlayers}** players)`,
      `- **Combined net worth:** ${formatReportGold(host.economy.totalNetWorth)}`,
      `- **Gold mined (all-time):** ${formatReportGold(host.economy.totalGoldMined ?? host.economy.totalGoldMinted)}`,
      `- **Shop listings:** **${host.economy.shopListings}**`,
    ];
    if (topPt) {
      const name = String(topPt.minecraft_username || "Unknown").trim() || "Unknown";
      lines.push(
        `- **Top playtime:** **${name}** at ${formatPlayLabel(Number(topPt.total_playtime_seconds) || 0)}`,
      );
    }
    if (topWallet) {
      lines.push(`- **Top wallet:** **${topWallet.player}** at ${topWallet.wallet_gold}`);
    }
    return lines.join("\n");
  };

  const comparison = formatHostComparisonAppendix(
    input.towny.economy,
    input.claims.economy,
    { towny: "Towny", claims: "Claims" },
    {
      towny: input.towny.playersWithPlaytime,
      claims: input.claims.playersWithPlaytime,
    },
  );

  const landNote =
    input.towny.townCount != null
      ? [
          "## Towny land (Towny-only)",
          "",
          `- **Towns / nations / plots:** **${input.towny.townCount ?? 0}** / **${input.towny.nationCount ?? 0}** / **${input.towny.totalPlots ?? 0}**`,
        ].join("\n")
      : "";

  return [
    "## Towny vs Claims",
    "",
    comparison,
    "",
    `_Realm-wide linked players (shared): **${input.linked}**_`,
    "",
    hostBlock("Towny", input.towny),
    "",
    hostBlock("Claims", input.claims),
    landNote ? `\n${landNote}` : "",
  ]
    .filter(Boolean)
    .join("\n");
}

/** Keep only Executive Summary + Outlook from model text; host sections are injected in code. */
export function extractExecutiveAndOutlook(reportText: string): {
  executive: string;
  outlook: string;
} {
  const text = String(reportText || "").trim();
  const pull = (title: string) => {
    const re = new RegExp(
      `##\\s*${title}\\s*\\n+([\\s\\S]*?)(?=\\n##\\s|$)`,
      "i",
    );
    const m = text.match(re);
    return m ? m[1].trim() : "";
  };
  let executive = pull("Executive Summary");
  let outlook = pull("Outlook");
  if (!executive && text && !/^##\s/m.test(text)) {
    executive = text.slice(0, 500);
  }
  return { executive, outlook };
}

export function composeDualHostDailyReportText(opts: {
  aiReportText: string;
  dualHostBody: string;
}): string {
  const { executive, outlook } = extractExecutiveAndOutlook(opts.aiReportText);
  const parts = [
    "## Executive Summary",
    "",
    executive || "_See Towny vs Claims below._",
    "",
    opts.dualHostBody.trim(),
  ];
  if (outlook) {
    parts.push("", "## Outlook", "", outlook);
  }
  return parts.join("\n").trim();
}

