): string {
  const hostBlock = (
    title: string,
    eco: EconomyTotals,
    rows: NetWorthRow[],
  ) => {
    const wallets = walletLeaderboardForPlayers(rows, 5);
    const netWorth = netWorthLeaderboardForPlayers(rows, 5);
    return [
      `**${title}**`,
      `- **Gold in wallets:** ${formatReportGold(eco.totalBalance)} (${eco.trackedPlayers} players)`,
      `- **Gold mined (all-time):** ${formatReportGold(eco.totalGoldMined ?? eco.totalGoldMinted)}`,
      `- **Combined net worth:** ${formatReportGold(eco.totalNetWorth)}`,
      `- **Shop listings:** ${eco.shopListings}`,
      wallets.length
        ? wallets.map((w) => `  ${w.rank}. ${w.player}  -  ${w.wallet_gold}`).join("\n")
        : "  _No wallet balances tracked._",
      netWorth.length
        ? netWorth.map((w) => `  ${w.rank}. ${w.player}  -  ${w.net_worth}`).join("\n")
        : "  _No net worth rankings yet._",
    ].join("\n");
  };

  const claimsEco = claims?.economy || {
    totalBalance: 0,
    totalNetWorth: 0,
    totalGoldMinted: 0,
    totalGoldMined: 0,
    shopListings: 0,
    pricedItems: 0,
    trackedPlayers: 0,
  };

  const parts = [
    `_Live economy snapshot  -  synced ${syncedAtLabel} HST_`,
    `_**Wallet Gold** = spendable balance only  -  **Net worth** = wallet + items + shop stock_`,
    `_Towny and Claims compared side-by-side — totals are never combined. Linked accounts are realm-wide._`,
    "",
    formatHostComparisonAppendix(
      economy,
      claimsEco,
      {
        towny: "Towny",
        claims: claims?.displayName || "Claims",
      },
      {
        towny: townyPlayersWithPlaytime,
        claims: claims?.playersWithPlaytime,
      },
    ),
    "",
    hostBlock("Towny detail", economy, netWorthRows),
  ];
  if (claims) {
    parts.push("", hostBlock(`${claims.displayName || "Claims"} detail`, claims.economy, claims.netWorth));
  }
  if (treasury) {
    parts.push("", formatTreasuryBriefAppendix(treasury, syncedAtLabel));
  }
  return parts.join("\n");
}

