        minecraft_username: string;
        balance: string;
        updated_at: string;
      }>();

    const rows = (bal.results || [])
      .map((row) => {
        const uuid = str(row.minecraft_uuid).toLowerCase();
        const name = str(row.minecraft_username);
        const balance = Number(row.balance);
        if (!uuid || !Number.isFinite(balance) || balance <= 0) return null;
        if (isEconomySystemAccount(uuid, name)) return null;
        return {
          minecraft_uuid: uuid,
          minecraft_username: name || null,
          balance_value: balance,
          // Placeholder only for row shape — callers must not sum this as net worth.
          total_value: 0,
          synced_at: str(row.updated_at) || null,
        };
      })
      .filter((row): row is NonNullable<typeof row> => row !== null);

    if (rows.length === 0) return null;

    const totalBalance = rows.reduce((s, r) => s + r.balance_value, 0);
    const syncedAt = rows.map((r) => r.synced_at).filter(Boolean).sort().pop() || null;
    const wallets = [...rows]
      .sort((a, b) => b.balance_value - a.balance_value)
      .slice(0, 15)
      .map((r) => ({
        minecraft_username: r.minecraft_username,
        total_value: 0,
        balance_value: r.balance_value,
      }));

    // LIVE balances are wallets only — never invent net worth from wallet totals.
    // Callers merge real net worth from main D1 (inventory + shop stock) when available.
    const goldRow = await liveDb
      .prepare(
        `SELECT COALESCE(SUM(CAST(total_gold_g AS REAL)), 0) AS mined
         FROM m_root_gold_found
         WHERE _server_id = ?`,
      )
      .bind(serverId)
      .first<{ mined: number }>();
    const goldMined = Math.max(0, Number(goldRow?.mined) || 0);

    return {
      economy: {
        trackedPlayers: rows.length,
        totalNetWorth: 0,
        totalBalance,
        totalGoldMinted: goldMined,
        totalGoldMined: goldMined,
        shopListings: null,
        pricedItems: 0,
        syncedAt,
      },
      wallets,
    };
  } catch (e) {
    console.warn(
      "rootmc_live_host_economy_slice_failed",
      serverId,
      e instanceof Error ? e.message : String(e),
    );
    return null;
  }
}

const claimsEconomy = liveClaims?.economy
  ? {
      ...liveClaims.economy,
      // Claims has no inventory net-worth pipeline yet — do not fake NW from wallets.
      totalNetWorth: claimsEconomyMain.totalNetWorth,
      shopListings: claimsShopListings,
      pricedItems: claimsEconomyMain.pricedItems,
      totalGoldMinted: liveClaims.economy.totalGoldMinted || claimsEconomyMain.totalGoldMinted,
      totalGoldMined: liveClaims.economy.totalGoldMined || claimsEconomyMain.totalGoldMined,
    }
  : { ...claimsEconomyMain, shopListings: claimsShopListings };

