  }
  return out;
}

const API = 'https://discord.com/api/v10';
const channels = ['1516395175780286615', '1516804780884889621'];
const env = readEnvFile(findCredentialsPath());
const token = String(process.env.DISCORD_ROOTMC_BOT_TOKEN || env.DISCORD_ROOTMC_BOT_TOKEN || '').replace(/^bot\s+/i, '').trim();
if (token.length < 40) { console.error('missing bot token'); process.exit(1); }

async function discordFetch(route, init = {}) {
  const headers = new Headers(init.headers || {});
  headers.set('Authorization', 'Bot ' + token);
  if (init.body && !headers.has('Content-Type')) headers.set('Content-Type', 'application/json');
  const res = await fetch(API + route, { ...init, headers });
  if (res.status === 429) {
    const j = await res.json().catch(() => ({}));
    const wait = Math.ceil(Number(j.retry_after || 1) * 1000) + 100;
    await new Promise((r) => setTimeout(r, wait));
    return discordFetch(route, init);
  }
  return res;
}

const twoWeeksAgo = Date.now() - 14 * 24 * 60 * 60 * 1000;

async function purgeChannel(channelId) {
  let deleted = 0;
  let failed = 0;
  let pages = 0;
  while (pages < 50) {
    pages++;
    const res = await discordFetch('/channels/' + channelId + '/messages?limit=100');
    const messages = await res.json().catch(() => []);
    if (!Array.isArray(messages) || messages.length === 0) break;

    const recent = [];
    const old = [];
    for (const msg of messages) {
      const ts = Number((BigInt(msg.id) >> 22n) + 1420070400000n);
      if (ts >= twoWeeksAgo) recent.push(msg.id);
      else old.push(msg.id);
    }

    while (recent.length >= 2) {
      const batch = recent.splice(0, Math.min(100, recent.length));
      if (batch.length === 1) { old.push(batch[0]); break; }
      const del = await discordFetch('/channels/' + channelId + '/messages/bulk-delete', {
        method: 'POST',
        body: JSON.stringify({ messages: batch }),
      });
      if (del.status === 204) deleted += batch.length;
      else {
        failed += batch.length;
        console.warn('bulk-delete failed', channelId, del.status, await del.text().catch(() => ''));
        // fall back to singles
        for (const id of batch) old.push(id);
      }
      await new Promise((r) => setTimeout(r, 400));
    }
    if (recent.length === 1) old.push(recent[0]);

    for (const id of old) {
      const del = await discordFetch('/channels/' + channelId + '/messages/' + id, { method: 'DELETE' });
      if (del.status === 204) deleted++;
      else {
        failed++;
        const t = await del.text().catch(() => '');
        console.warn('delete failed', channelId, id, del.status, t.slice(0, 120));
      }
      await new Promise((r) => setTimeout(r, 350));
    }

    if (messages.length < 100) {
      // re-check once more in case new pages
      const again = await discordFetch('/channels/' + channelId + '/messages?limit=100');
      const more = await again.json().catch(() => []);
      if (!Array.isArray(more) || more.length === 0) break;
      // continue loop to delete remaining
    }
  }
  return { deleted, failed };
}

for (const id of channels) {
  console.log('purging', id, '...');
  const result = await purgeChannel(id);
  console.log('done', id, result);
}
"

