    `- **Members:** **${Math.max(0, Math.floor(Number(input.memberCount) || 0))}**`,
    `- **Messages yesterday:** **${Math.max(0, Math.floor(Number(input.totalMessages) || 0))}**`,
  ];
  if (input.topChannels.length) {
    lines.push(
      `- **Busiest channels:** ${input.topChannels
        .slice(0, 5)
        .map((c) => `**#${String(c.name || "channel").replace(/^#/, "")}** (${c.count})`)
        .join("; ")}`,
    );
  }
  const highlights = (input.highlights || []).slice(0, 8);
  if (highlights.length) {
    lines.push("", "**Highlights**");
    for (const h of highlights) {
      const ch = String(h.channel || "channel").replace(/^#/, "");
      const who = String(h.author || "member").trim() || "member";
      const title = h.thread_title ? ` · ${String(h.thread_title).slice(0, 80)}` : "";
      const body = String(h.content || "").replace(/\s+/g, " ").trim().slice(0, 220);
      if (!body) continue;
      lines.push(`- **#${ch}** (${who}${title}): ${body}`);
    }
  } else {
    lines.push("", "_No substantive Discord highlights in the window._");
  }
  return lines.join("\n");
}

