/** HST calendar day for the MC-midnight period (00:30 boundary). */
export function previousHstDayKey(at = new Date()): string {
  const hstMs = at.getTime() - HST_OFFSET_MS;
  const hst = new Date(hstMs);
  let y = hst.getUTCFullYear();
  let m = hst.getUTCMonth();
  let day = hst.getUTCDate();
  const minuteOfDay = hst.getUTCHours() * 60 + hst.getUTCMinutes();
  const daysBack = minuteOfDay < 30 ? 2 : 1;
  const start = new Date(Date.UTC(y, m, day) - daysBack * 24 * 60 * 60 * 1000);
  y = start.getUTCFullYear();
  m = start.getUTCMonth();
  day = start.getUTCDate();
  return `${y}-${String(m + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
}

function hstDayBoundsMs(dayKey: string): { startMs: number; endMs: number } {
  const startMs = Date.parse(`${dayKey}T00:30:00-10:00`);
  const endMs = startMs + 24 * 60 * 60 * 1000 - 1;
  return { startMs, endMs };
